CREATE TABLE customers (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    full_name text NOT NULL,
    email text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    profile jsonb NOT NULL DEFAULT '{}'::jsonb,
    active boolean NOT NULL DEFAULT true,
    CONSTRAINT customers_name_check CHECK (length(full_name) > 0)
);
CREATE TABLE products (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sku text NOT NULL,
    name text NOT NULL,
    category text NOT NULL,
    price numeric(10, 2) NOT NULL CHECK (price >= 0),
    attributes jsonb NOT NULL DEFAULT '{}'::jsonb
);
CREATE TABLE orders (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_id bigint NOT NULL,
    status text NOT NULL CHECK (status IN ('pending', 'paid', 'shipped', 'cancelled')),
    ordered_at timestamptz NOT NULL,
    total numeric(12, 2) NOT NULL CHECK (total >= 0),
    details jsonb NOT NULL DEFAULT '{}'::jsonb
);
CREATE TABLE order_items (
    order_id bigint NOT NULL,
    product_id bigint NOT NULL,
    quantity integer NOT NULL CHECK (quantity > 0),
    unit_price numeric(10, 2) NOT NULL CHECK (unit_price >= 0),
    PRIMARY KEY (order_id, product_id)
);
CREATE SEQUENCE audit_log_id_seq CACHE 1;
CREATE TABLE audit_log (
    id bigint PRIMARY KEY DEFAULT nextval('audit_log_id_seq'),
    entity_type text NOT NULL,
    entity_id bigint NOT NULL,
    action text NOT NULL CHECK (action IN ('created', 'updated', 'deleted')),
    details jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE VIEW customer_order_totals AS
SELECT c.id AS customer_id, c.full_name, count(o.id) AS order_count, coalesce(sum(o.total), 0) AS lifetime_total
FROM customers AS c LEFT JOIN orders AS o ON o.customer_id = c.id GROUP BY c.id, c.full_name;
CREATE VIEW product_sales AS
SELECT p.id AS product_id, p.sku, p.name, coalesce(sum(i.quantity), 0) AS units_sold
FROM products AS p LEFT JOIN order_items AS i ON i.product_id = p.id GROUP BY p.id, p.sku, p.name;
COMMENT ON TABLE customers IS 'Customer records used by paging and filtering examples';
COMMENT ON COLUMN customers.profile IS 'Customer JSONB profile data';
COMMENT ON TABLE audit_log IS 'Append-only audit history';
INSERT INTO customers (full_name, email, created_at, profile, active)
SELECT 'Customer ' || i, 'customer' || i || '@example.test', timestamptz '2025-01-01 00:00:00+00' + i * interval '1 minute', jsonb_build_object('tier', CASE WHEN i % 4 = 0 THEN 'gold' ELSE 'standard' END, 'rank', i), i % 10 <> 0
FROM generate_series(1, 1000) AS i;
INSERT INTO products (sku, name, category, price, attributes)
SELECT 'SKU-' || lpad(i::text, 3, '0'), 'Product ' || i, CASE WHEN i % 2 = 0 THEN 'hardware' ELSE 'software' END, (i * 7.25)::numeric(10, 2), jsonb_build_object('weight_grams', i * 20, 'featured', i % 3 = 0)
FROM generate_series(1, 12) AS i;
INSERT INTO orders (customer_id, status, ordered_at, total, details)
SELECT (i % 1000) + 1, CASE WHEN i % 4 = 0 THEN 'pending' WHEN i % 4 = 1 THEN 'paid' WHEN i % 4 = 2 THEN 'shipped' ELSE 'cancelled' END, timestamptz '2025-03-01 00:00:00+00' + i * interval '10 minutes', (i * 3.50)::numeric(12, 2), jsonb_build_object('source', CASE WHEN i % 2 = 0 THEN 'web' ELSE 'mobile' END, 'priority', i % 5 = 0)
FROM generate_series(1, 1500) AS i;
INSERT INTO order_items (order_id, product_id, quantity, unit_price)
SELECT floor((i - 1) / 12)::int + 1, ((i - 1) % 12) + 1, (i % 5) + 1, (((i % 12)::numeric + 1::numeric) * 7.25)::numeric(10, 2)
FROM generate_series(1, 2500) AS i;
INSERT INTO audit_log (entity_type, entity_id, action, details, created_at)
SELECT CASE WHEN i % 2 = 0 THEN 'customer' ELSE 'order' END, i, CASE WHEN i % 3 = 0 THEN 'updated' ELSE 'created' END, jsonb_build_object('sequence', i, 'actor', 'seed'), timestamptz '2025-04-01 00:00:00+00' + i * interval '1 minute'
FROM generate_series(1, 500) AS i;
CREATE UNIQUE INDEX ASYNC customers_email_unique_idx ON customers (email);
CREATE UNIQUE INDEX ASYNC products_sku_unique_idx ON products (sku);
CREATE INDEX ASYNC orders_customer_ordered_idx ON orders (customer_id, ordered_at);
CREATE INDEX ASYNC audit_log_entity_idx ON audit_log (entity_type, entity_id);
